import {LANDMARK_NAMES,detectHatLandmarks,headLandmarks,fitHatToHead,referenceHeadLandmarks,validateHeadFit} from './head-fit.mjs';
const clone=p=>structuredClone(p),colors=['#ffbc78','#70ddff','#c2f58c'];
export function mountHeadFitting(actions){
 const section=document.createElement('section');section.className='head-fit-panel';
 section.innerHTML='<h3>TỰ CĂN MŨ ÔM ĐẦU</h3><p>Dành cho mũ giáp / mũ ôm đầu. Ước lượng vùng thân để giảm ảnh hưởng của tai, sừng, cánh. Đây là phân tích hình dáng, không đảm bảo hiểu đúng mọi thiết kế; hãy kiểm tra ba mốc. Tắt tự căn khi tải mũ vành hoặc tai nghe.</p><label>Căn theo<select id="hatFitReference"><option value="auto">Mũ đang đeo khác, nếu có; nếu không dùng đầu</option><option value="head">Đầu nhân vật</option></select></label><button id="autoFitHat">◎ Nhận diện mốc & tự căn mũ</button><p id="hatFitInfo" role="status"></p><details id="hatFitDetails"><summary>Kiểm tra / chỉnh ba mốc ôm đầu</summary><label>Mốc đang chỉnh<select id="hatFitPoint"><option value="0">Trán</option><option value="1">Gáy</option><option value="2">Cằm</option></select></label><p>Chạm gần chấm để kéo, hoặc chọn tên mốc rồi chạm vị trí mới. Chỉnh xong bấm Áp dụng. Đặt mốc lên phần ôm đầu, không đặt ở chóp tai / cánh.</p><label>Trên ảnh mũ<canvas id="hatFitSource" width="300" height="230"></canvas></label><label>Vị trí tương ứng trên đầu<canvas id="hatFitHead" width="300" height="230"></canvas></label><button id="applyHatFit">Áp dụng ba mốc · tự chỉnh cỡ</button></details>';
 actions.container.querySelector('#attachmentPreview').before(section);
 const autoLabel=document.createElement('label');autoLabel.className='hat-fit-upload';autoLabel.innerHTML='<input type="checkbox" id="autoHatFitUpload" checked> Tự căn mũ ôm đầu khi tải ảnh (có thể Hoàn tác)';actions.container.querySelector('#uploadAccessory').before(autoLabel);
 const $=id=>section.querySelector('#'+id),message=actions.message;let pending=null,pendingId=null,images=null,version=0,gesture=null,rects={},savedSignature='',lastSrc='';
 const safe=fn=>async e=>{try{await fn(e)}catch(error){message('Căn mũ: '+error.message);$('hatFitInfo').textContent=error.message}};
 function pixels(img){const k=Math.min(1,224/Math.max(img.naturalWidth,img.naturalHeight)),c=document.createElement('canvas');c.width=Math.max(2,Math.round(img.naturalWidth*k));c.height=Math.max(2,Math.round(img.naturalHeight*k));const ctx=c.getContext('2d');ctx.drawImage(img,0,0,c.width,c.height);return {data:ctx.getImageData(0,0,c.width,c.height).data,w:c.width,h:c.height}}
 const detect=img=>{const p=pixels(img);return detectHatLandmarks(p.data,p.w,p.h)};
 const targetHead=img=>{const p=pixels(img);return headLandmarks(p.data,p.w,p.h)};
 function referenceFor(a){const value=$('hatFitReference').value,candidates=actions.items().filter(b=>b.id!==a.id&&b.socket==='head');return value==='head'?null:value==='auto'?candidates.filter(b=>b.visible!==false).at(-1):candidates.find(b=>b.id===value)}
 async function estimate(a){const head=actions.head(),[sourceImage,headImage]=await Promise.all([actions.image(a.src),actions.image(head.src)]),detected=detect(sourceImage),reference=referenceFor(a);let target=targetHead(headImage);
  if(reference){const ri=await actions.image(reference.src),points=reference.headFit?.points||detect(ri).points;target=referenceHeadLandmarks(reference,points,head)}
  return {fit:{version:1,method:'silhouette-core',points:detected.points,target,confidence:detected.confidence},images:{source:sourceImage,head:headImage},reference:reference?.name||'đầu nhân vật'};
 }
 function show(){if(!images)return;for(const [key,id]of [['source','hatFitSource'],['head','hatFitHead']]){const canvas=$(id),ctx=canvas.getContext('2d'),img=images[key],points=key==='source'?pending?.points:pending?.target;let x0=0,y0=0,x1=1,y1=1;if(points&&key==='head'){x0=Math.min(0,...points.map(p=>p[0]));x1=Math.max(1,...points.map(p=>p[0]));y0=Math.min(0,...points.map(p=>p[1]));y1=Math.max(1,...points.map(p=>p[1]))}const k=Math.min(266/(img.naturalWidth*(x1-x0)),196/(img.naturalHeight*(y1-y0))),w=img.naturalWidth*k,h=img.naturalHeight*k;const r=gesture?.key===key?gesture.rect:{x:(300-w*(x1-x0))/2-x0*w,y:(230-h*(y1-y0))/2-y0*h,w,h};rects[key]=r;ctx.clearRect(0,0,300,230);ctx.drawImage(img,r.x,r.y,r.w,r.h);if(points){ctx.lineWidth=1.3;ctx.strokeStyle='#e0ecbd99';ctx.beginPath();points.forEach((p,i)=>ctx[i?'lineTo':'moveTo'](r.x+p[0]*r.w,r.y+p[1]*r.h));ctx.closePath();ctx.stroke();points.forEach((p,i)=>{const x=r.x+p[0]*r.w,y=r.y+p[1]*r.h;ctx.fillStyle=colors[i];ctx.beginPath();ctx.arc(x,y,6,0,7);ctx.fill();ctx.fillStyle='#fff';ctx.font='11px sans-serif';ctx.fillText(LANDMARK_NAMES[i],x+8,y-6)})}}}
 async function refresh(){const a=actions.current();section.hidden=!a||a.socket!=='head';autoLabel.hidden=actions.category()!=='hat';if(section.hidden)return;
  const old=$('hatFitReference').value,candidates=actions.items().filter(b=>b.id!==a.id&&b.socket==='head');$('hatFitReference').replaceChildren(new Option('Mũ đang đeo khác, nếu có; nếu không dùng đầu','auto'),new Option('Đầu nhân vật','head'),...candidates.map(b=>new Option(b.name,b.id)));$('hatFitReference').value=[...$('hatFitReference').options].some(o=>o.value===old)?old:'auto';
  const signature=JSON.stringify(a.headFit||null);if(pendingId!==a.id||savedSignature!==signature||lastSrc!==a.src){pendingId=a.id;savedSignature=signature;lastSrc=a.src;pending=a.headFit?clone(a.headFit):null;$('hatFitInfo').textContent=pending?'Có ba mốc đã lưu; có thể chỉnh và áp dụng lại.':'Bấm Nhận diện để ước lượng mốc; kính và vũ khí không bị thay đổi.'}
  const v=++version,head=actions.head(),pair=await Promise.all([actions.image(a.src),actions.image(head.src)]);if(v!==version||actions.current()?.id!==a.id)return;images={source:pair[0],head:pair[1]};show();
 }
 async function apply(){const a=actions.current();if(!a||a.socket!=='head')throw Error('Chọn một mũ gắn trên đầu');if(!pending||pendingId!==a.id){const r=await estimate(a);pending=r.fit;pendingId=a.id;images=r.images}validateHeadFit(pending);show();$('hatFitDetails').open=true;
  if(pending.confidence<.45&&pending.method!=='manual'){$('hatFitInfo').textContent='Ảnh chưa có nền trong suốt / vùng thân chưa rõ. Hãy chỉnh ba mốc bằng tay rồi Áp dụng; chưa đổi kích thước.';message($('hatFitInfo').textContent);return}
  if(actions.current()?.id!==a.id||actions.current()?.src!==a.src)throw Error('Mũ vừa thay đổi; hãy nhận diện lại');
  const head=actions.head(),fit=clone(pending),width=images.source.naturalWidth,height=images.source.naturalHeight;
  await actions.mutate(items=>{const i=items.findIndex(b=>b.id===a.id);if(i<0)throw Error('Mũ đã thay đổi');items[i]=fitHatToHead(items[i],fit,width,height,head)});
  $('hatFitInfo').textContent='Đã căn theo ba mốc, giữ tỷ lệ gốc của ảnh. Kiểm tra độ ôm trên preview; có thể Hoàn tác.';message('Đã tự căn mũ ôm đầu; kính / món khác giữ nguyên. Có thể Hoàn tác.');
 }
 $('autoFitHat').onclick=safe(async()=>{const a=actions.current();if(!a||a.socket!=='head')return;const r=await estimate(a);if(actions.current()?.id!==a.id)throw Error('Mũ đang chọn vừa thay đổi');pending=r.fit;pendingId=a.id;images=r.images;await apply()});
 $('applyHatFit').onclick=safe(apply);$('hatFitReference').onchange=safe(async()=>{const a=actions.current();if(!a)return;const r=await estimate(a);pending=r.fit;pendingId=a.id;images=r.images;$('hatFitDetails').open=true;show();$('hatFitInfo').textContent='Đã lấy mốc theo '+r.reference+'. Bấm Áp dụng để đổi cỡ.'});
 for(const [key,id]of [['source','hatFitSource'],['head','hatFitHead']]){const canvas=$(id),points=()=>key==='source'?pending.points:pending.target;const move=e=>{if(!gesture||gesture.key!==key||e.pointerId!==gesture.pointer)return;e.preventDefault();const b=canvas.getBoundingClientRect(),r=gesture.rect,x=((e.clientX-b.left)*300/b.width-r.x)/r.w,y=((e.clientY-b.top)*230/b.height-r.y)/r.h,lo=key==='source'?0:-2,hi=key==='source'?1:3;points()[gesture.index]=[Math.max(lo,Math.min(hi,x)),Math.max(lo,Math.min(hi,y))];pending.method='manual';pending.confidence=1;show();$('hatFitInfo').textContent='Mốc đã chỉnh tay; bấm Áp dụng ba mốc để tự tính lại kích thước.'};canvas.onpointerdown=e=>{if(!pending||!rects[key]){message('Bấm Nhận diện mốc trước khi chỉnh');return}e.preventDefault();const b=canvas.getBoundingClientRect(),r=rects[key],x=(e.clientX-b.left)*300/b.width,y=(e.clientY-b.top)*230/b.height;let index=Number($('hatFitPoint').value),best=20;points().forEach((p,i)=>{const d=Math.hypot(r.x+p[0]*r.w-x,r.y+p[1]*r.h-y);if(d<best){index=i;best=d}});$('hatFitPoint').value=index;gesture={key,index,pointer:e.pointerId,rect:{...r},original:clone(pending)};canvas.setPointerCapture(e.pointerId);move(e)};canvas.onpointermove=move;canvas.onpointerup=e=>{if(!gesture||gesture.pointer!==e.pointerId)return;move(e);gesture=null;show()};canvas.onpointercancel=()=>{if(gesture)pending=gesture.original;gesture=null;show()};canvas.onlostpointercapture=()=>{gesture=null;show()};canvas.oncontextmenu=e=>e.preventDefault()}
 return {refresh,async fitUpload(a){if(!autoLabel.querySelector('input').checked)return {attachment:a};try{const r=await estimate(a);if(r.fit.confidence<.45)return {attachment:{...a,headFit:r.fit},notice:'Đã tải mũ; ảnh khó nhận diện, chưa đổi cỡ. Mở ba mốc để chỉnh tay.'};return {attachment:fitHatToHead(a,r.fit,r.images.source.naturalWidth,r.images.source.naturalHeight,actions.head()),notice:'Đã tải và tự căn mũ theo vùng ôm đầu (mốc ước lượng). Kiểm tra preview; có thể Hoàn tác.'}}catch(error){return {attachment:a,notice:'Đã tải mũ; chưa tự căn: '+error.message}}}};
}
